import React, { useState, useEffect, useMemo, useContext } from 'react';
import { StaffRolesContext } from '../StaffRolesContext';
// --- Helper Components & Icons ---

const InfoIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{ color: '#6c757d', cursor: 'pointer' }}>
        <circle cx="12" cy="12" r="10"></circle>
        <line x1="12" y1="16" x2="12" y2="12"></line>
        <line x1="12" y1="8" x2="12.01" y2="8"></line>
    </svg>
);

const EditIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{ cursor: 'pointer', color: '#495057' }}>
        <path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"></path>
        <path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"></path>
    </svg>
);

const SaveIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
        <path d="M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2z"></path>
        <polyline points="17 21 17 13 7 13 7 21"></polyline>
        <polyline points="7 3 7 8 15 8"></polyline>
    </svg>
);
const Toast = ({ message, type, onHide }) => {
    useEffect(() => {
        const timer = setTimeout(onHide, 3000);
        return () => clearTimeout(timer);
    }, [onHide]);
    return <div style={{...styles.toast, backgroundColor: type === 'success' ? '#28a745' : '#dc3545'}}>{message}</div>;
};

const Modal = ({ isOpen, onClose, onConfirm, title, children }) => {
    if (!isOpen) return null;
    return (
        <div style={styles.modalOverlay} onClick={onClose}>
            <div style={styles.modalContent} onClick={e => e.stopPropagation()}>
                <h4 style={styles.modalTitle}>{title}</h4>
                <p style={styles.modalBody}>{children}</p>
                <div style={styles.modalFooter}>
                    <button style={styles.modalButton('secondary')} onClick={onClose}>Cancel</button>
                    <button style={styles.modalButton('primary')} onClick={onConfirm}>Confirm</button>
                </div>
            </div>
        </div>
    );
};
// --- Main Component ---
// 1. Accept `definedRoles` as a prop
export default function PerStudentAllocationTab({ onAllocationChange }) {

    const { definedRoles } = useContext(StaffRolesContext);
    // --- State and Calculations ---
    const [numberOfStudents, setNumberOfStudents] = useState(100);
    const [adminLoading, setAdminLoading] = useState(0.0);
    const [details, setDetails] = useState('');

    // 2. Initialize state with only the fixed Subject Coordinator role
    const [allocations, setAllocations] = useState([
        { id: 'coord', role: 'Subject Coordinator', marking: 0, consultation: 0.0025, coordination: 0.00125 },
    ]);
    const [errors, setErrors] = useState({});

    const BASE_RATE_PER_25 = 0.03;
    const totalRatePer25 = useMemo(() => BASE_RATE_PER_25 + adminLoading, [adminLoading]);
    const totalPerStudentAllocation = useMemo(() => (numberOfStudents > 0 ? (numberOfStudents / 25) * totalRatePer25 : 0), [numberOfStudents, totalRatePer25]);

    useEffect(() => {
        if (onAllocationChange) {
            onAllocationChange(totalPerStudentAllocation);
        }
    }, [totalPerStudentAllocation, onAllocationChange]);

    useEffect(() => {
        setAllocations(currentAllocations => {
            const coordinator = currentAllocations.find(a => a.id === 'coord') || 
                                { id: 'coord', role: 'Subject Coordinator', /*...*/ };

            const syncedRoles = definedRoles.map(propRole => {
                const existing = currentAllocations.find(a => a.id === propRole.id);
                return existing ? { ...existing, role: propRole.name } : { 
                    id: propRole.id, 
                    role: propRole.name, 
                    marking: 0, consultation: 0, coordination: 0 
                };
            });
            return [coordinator, ...syncedRoles];
        });
    }, [definedRoles]);

    // --- Helper Functions ---
    const showToast = (message, type = 'error') => setToast({ show: true, message, type });

    const openModal = (type, title, message) => setModal({ isOpen: true, type, title, message });

    // --- Handlers for Editing ---
    const handleEditClick = (item) => {
        setEditingId(item.id);
        setTempAllocation({ ...item });
    };

    const handleCancelClick = () => {
        setEditingId(null);
        setTempAllocation(null);
    };

    const handleTempChange = (field, value) => {
        const parsedValue = parseFloat(value);
        if (parsedValue < 0) return; // Prevent negative values
        setTempAllocation(prev => ({ ...prev, [field]: isNaN(parsedValue) ? 0 : parsedValue / 100 }));
    };

    const confirmUpdate = () => {
        const otherAllocationsSum = allocations
            .filter((_, i) => allocations[i].id !== editingId)
            .reduce((sum, item) => sum + item.marking + item.consultation + item.coordination, 0);

        const newTotalSum = otherAllocationsSum + tempAllocation.marking + tempAllocation.consultation + tempAllocation.coordination;

        if (newTotalSum > totalRatePer25) {
            showToast(`Update failed. Total allocation cannot exceed ${(totalRatePer25 * 100).toFixed(3)}%.`);
            setModal({ ...modal, isOpen: false });
            return;
        }

        setAllocations(allocations.map(a => (a.id === editingId ? tempAllocation : a)));
        handleCancelClick(); // Reset editing state
        showToast('Allocation updated successfully.', 'success');
        setModal({ ...modal, isOpen: false });
    };

    const confirmSaveAll = () => {
        if (editingId) {
            showToast('Please save or cancel the row you are currently editing.');
            setModal({ ...modal, isOpen: false });
            return;
        }
        if (currentDistributedSum > totalRatePer25) {
            showToast(`Cannot save. Total allocation exceeds the maximum allowed rate.`);
            setModal({ ...modal, isOpen: false });
            return;
        }
        // In a real app, you would send the data to a server here.
        console.log('Saving all data:', { numberOfStudents, adminLoading, details, allocations });
        showToast('All changes saved successfully!', 'success');
        setModal({ ...modal, isOpen: false });
    };

    const handleModalConfirm = () => {
        if (modal.type === 'updateRow') {
            confirmUpdate();
        } else if (modal.type === 'saveAll') {
            confirmSaveAll();
        }
    };


    // --- Component Render ---
    return (
        <>{toast.show && <Toast message={toast.message} type={toast.type} onHide={() => setToast({ ...toast, show: false })} />}
            <Modal 
                isOpen={modal.isOpen}
                onClose={() => setModal({ ...modal, isOpen: false })}
                onConfirm={handleModalConfirm}
                title={modal.title}
            >
                {modal.message}
            </Modal>
        <div style={styles.container}>
            {/* --- Top Level Inputs --- */}
            <div style={styles.inputGroup}>
                <label style={styles.label} htmlFor="totalAllocation">Per-student Allocation <InfoIcon /></label>
                <input style={{...styles.input, ...styles.readOnlyInput}} id="totalAllocation" type="text" value={`${(totalPerStudentAllocation * 100).toFixed(1)}%`} readOnly />
            </div>
            <div style={styles.inputGroup}>
                <label style={styles.label} htmlFor="numStudents">Number of students</label>
                <input style={styles.input} id="numStudents" type="number" value={numberOfStudents} onChange={(e) => setNumberOfStudents(parseInt(e.target.value, 10) || 0)} />
            </div>
            <div style={styles.inputGroup}>
                <label style={styles.label} htmlFor="adminLoading">Administrative loading per 25 students <InfoIcon /></label>
                <input style={styles.input} id="adminLoading" type="text" value={`${(adminLoading * 100).toFixed(1)}%`} onChange={(e) => setAdminLoading(parseFloat(e.target.value.replace('%','')) / 100 || 0)} />
            </div>
            <div style={{...styles.inputGroup, maxWidth: 'unset'}}>
                <label style={styles.label} htmlFor="details">Details</label>
                <textarea style={styles.textarea} id="details" placeholder="If a claim is made, provide details." value={details} onChange={(e) => setDetails(e.target.value)}></textarea>
            </div>

            {/* --- Distribution Table --- */}
            <div style={styles.tableContainer}>
                    <div style={styles.tableHeader}>
                        <h3 style={styles.tableTitle}>Per 25 students</h3>
                        <InfoIcon title={`Distribution of the ${ (totalRatePer25 * 100).toFixed(3) }% rate.`} />
                    </div>
                    {currentDistributedSum > totalRatePer25 && <div style={styles.errorBox}>Warning: The sum of distributed allocations ({`${(currentDistributedSum * 100).toFixed(3)}%`}) exceeds the total available rate.</div>}
                    <table style={styles.table}>
                        <thead>
                            <tr>
                                <th style={{...styles.th, ...styles.leftAlign}}>Actions</th>
                                <th style={{...styles.th, ...styles.leftAlign}}>Staff Role</th>
                                <th style={styles.th}>Marking</th>
                                <th style={styles.th}>Consultation</th>
                                <th style={styles.th}>Coordination</th>
                            </tr>
                        </thead>
                        <tbody>
                            {allocations.map((item) => (
                                <tr key={item.id}>
                                    <td style={{...styles.td, ...styles.leftAlign}}>
                                        {editingId === item.id ? (
                                            <>
                                                <button onClick={() => openModal('updateRow', 'Confirm Update', 'Are you sure you want to save these changes?')} style={styles.actionButton('primary')}>Update</button>
                                                <button onClick={handleCancelClick} style={styles.actionButton('secondary')}>Cancel</button>
                                            </>
                                        ) : (
                                            <button onClick={() => handleEditClick(item)} style={{...styles.iconButton, opacity: editingId ? 0.5 : 1}} disabled={editingId !== null} title="Edit"><EditIcon /></button>
                                        )}
                                    </td>
                                    <td style={{...styles.td, ...styles.leftAlign}}>{item.role}</td>
                                    {['marking', 'consultation', 'coordination'].map(field => (
                                        <td style={styles.td} key={field}>
                                            {editingId === item.id ? (
                                                <input type="number" step="0.001" style={styles.tableInput} value={(tempAllocation[field] * 100).toFixed(3)} onChange={e => handleTempChange(field, e.target.value)} />
                                            ) : ( `${(item[field] * 100).toFixed(3)}%` )}
                                        </td>
                                    ))}
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>

                <div style={styles.buttonContainer}>
                    <button style={styles.saveButton} onClick={() => openModal('saveAll', 'Confirm Save', 'Are you sure you want to save all changes on this page?')}>
                        <SaveIcon />
                        Save
                    </button>
                </div>
            </div>

        </>

    );
}
// --- Styles ---
const styles = {
    container: { backgroundColor: '#fff', padding: '2rem', borderRadius: '8px', border: '1px solid #dee2e6' },
    inputGroup: { display: 'flex', flexDirection: 'column', gap: '0.5rem', marginBottom: '1.5rem', maxWidth: '400px' },
    label: { color: '#212529', fontWeight: '600', fontSize: '1rem', display: 'flex', alignItems: 'center', gap: '0.5rem' },
    input: { padding: '0.6rem 0.75rem', border: '1px solid #ced4da', borderRadius: '4px', fontSize: '1rem', backgroundColor: '#fff' },
    readOnlyInput: { backgroundColor: '#f8f9fa', color: '#495057' },
    textarea: { padding: '0.75rem', border: '1px solid #ced4da', borderRadius: '4px', fontSize: '1rem', minHeight: '80px', resize: 'vertical' },
    tableContainer: { marginTop: '2.5rem' },
    tableHeader: { display: 'flex', alignItems: 'center', gap: '0.5rem', marginBottom: '1rem' },
    tableTitle: { margin: 0, fontSize: '1.25rem', fontWeight: '600', color: '#212529' },
    table: { width: '100%', borderCollapse: 'collapse', borderSpacing: 0 },
    th: { padding: '0.75rem 1rem', textAlign: 'center', borderBottom: '2px solid #dee2e6', color: '#6c757d', fontWeight: '500', fontSize: '0.9rem', textTransform: 'uppercase' },
    td: { padding: '1rem', textAlign: 'center', borderBottom: '1px solid #e9ecef', color: '#212529', fontSize: '0.95rem' },
    leftAlign: { textAlign: 'left' },
    tableInput: { width: '80%', padding: '0.5rem', border: '1px solid #ced4da', borderRadius: '4px', textAlign: 'center' },
    iconButton: { background: 'none', border: 'none', cursor: 'pointer', padding: 0 },
    actionButton: (variant) => ({
        background: variant === 'primary' ? '#007bff' : '#6c757d',
        color: 'white',
        border: 'none',
        padding: '0.3rem 0.6rem',
        borderRadius: '4px',
        cursor: 'pointer',
        marginRight: '0.5rem',
        fontSize: '0.9rem'
    }),
    buttonContainer: { display: 'flex', justifyContent: 'flex-start', marginTop: '2rem' },
    saveButton: { backgroundColor: '#212529', color: 'white', padding: '0.6rem 1.5rem', border: 'none', borderRadius: '6px', cursor: 'pointer', fontWeight: '500', display: 'flex', alignItems: 'center', gap: '0.5rem', fontSize: '1rem' },
    errorBox: { backgroundColor: '#f8d7da', color: '#721c24', border: '1px solid #f5c6cb', borderRadius: '4px', padding: '1rem', marginBottom: '1rem' },
    toast: { position: 'fixed', top: '20px', right: '20px', padding: '1rem 1.5rem', borderRadius: '8px', color: 'white', boxShadow: '0 4px 15px rgba(0,0,0,0.2)', zIndex: 1050 },
    modalOverlay: { position: 'fixed', top: 0, left: 0, right: 0, bottom: 0, backgroundColor: 'rgba(0, 0, 0, 0.6)', zIndex: 1000, display: 'flex', alignItems: 'center', justifyContent: 'center' },
    modalContent: { backgroundColor: 'white', padding: '2rem', borderRadius: '8px', maxWidth: '500px', width: '90%', boxShadow: '0 5px 20px rgba(0,0,0,0.3)' },
    modalTitle: { marginTop: 0, color: '#343a40' },
    modalBody: { color: '#495057', lineHeight: '1.6' },
    modalFooter: { marginTop: '1.5rem', paddingTop: '1rem', borderTop: '1px solid #e9ecef', display: 'flex', justifyContent: 'flex-end', gap: '1rem' },
    modalButton: (variant) => ({ padding: '0.6rem 1.2rem', fontSize: '1rem', borderRadius: '6px', border: 'none', cursor: 'pointer', fontWeight: '500', color: 'white', backgroundColor: variant === 'primary' ? '#007bff' : '#6c757d' }),
};
